import httpx
import time
import logging
from typing import Optional, Any
from functools import wraps

logger = logging.getLogger(__name__)

def retry_with_backoff(max_retries: int = 3, base_delay: float = 1.0):
    """EGRR_PATTERN: Decorator for retry with exponential backoff."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_exception = None
            for attempt in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except (httpx.ConnectError, httpx.TimeoutException) as e:
                    last_exception = e
                    delay = base_delay * (2 ** attempt)
                    logger.warning(f'Attempt {attempt + 1} failed: {e}. Retrying in {delay}s')
                    time.sleep(delay)
            raise last_exception
        return wrapper
    return decorator

@retry_with_backoff(max_retries=3)
def safe_http_get(url: str, timeout: float = 10.0) -> Optional[dict]:
    """EGRR_PATTERN: Safe HTTP GET with comprehensive error handling."""
    try:
        with httpx.Client(timeout=timeout) as client:
            response = client.get(url)
            response.raise_for_status()
            return response.json()

    except httpx.HTTPStatusError as e:
        logger.error(f'HTTP {e.response.status_code} error for {url}')
        return None
    except httpx.RequestError as e:
        logger.error(f'Request error for {url}: {e}')
        return None
    except ValueError as e:  # JSON decode error
        logger.error(f'Invalid JSON response from {url}: {e}')
        return None

async def safe_async_request(url: str, method: str = 'GET', **kwargs) -> Optional[Any]:
    """EGRR_PATTERN: Safe async HTTP request with timeout."""
    try:
        async with httpx.AsyncClient(timeout=30.0) as client:
            response = await client.request(method, url, **kwargs)
            response.raise_for_status()
            return response.json()
    except httpx.TimeoutException:
        logger.error(f'Request timeout for {url}')
        return None
    except httpx.HTTPStatusError as e:
        logger.error(f'HTTP error {e.response.status_code}: {url}')
        return None
    except Exception as e:
        logger.error(f'Unexpected error requesting {url}: {e}')
        return None
